// Aplatit la sortie NocoDB v3 {id, fields:{}} au format plat du noeud
// Airtable historique : {...champs, id} -> aucune expression aval a changer.
return $input.all().map(i => ({ json: { ...(i.json.fields || {}), id: i.json.id } }));

// Découpe chaque contenu rédigé en cartes à rendre — une par slide.
const MAX_CARTES = 10;

function lireCartes(raw) {
  let v = raw;
  if (typeof v === 'string') {
    if (!v.trim()) return [];
    try { v = JSON.parse(v); } catch (e) { return []; }
  }
  if (!Array.isArray(v)) return [];
  const out = [];
  for (const s of v) {
    const o = (s && typeof s === 'object') ? s : { titre: String(s == null ? '' : s) };
    const titre = String(o.titre || '').trim();
    if (!titre) continue; // une carte sans titre ne se rend pas : autant la jeter ici
    const carte = { titre: titre };
    if (String(o.corps || '').trim()) carte.corps = String(o.corps).trim();
    if (String(o.cta || '').trim()) carte.cta = String(o.cta).trim();
    if (Array.isArray(o.options)) {
      const opts = o.options.map(x => String(x == null ? '' : x).trim()).filter(Boolean).slice(0, 4);
      if (opts.length >= 2) carte.options = opts; // un sondage à une seule réponse n'en est pas un
    }
    out.push(carte);
    if (out.length >= MAX_CARTES) break;
  }
  return out;
}

const out = [];
for (const item of $input.all()) {
  const r = item.json || {};
  let cartes = lireCartes(r.Slides_JSON);
  const fmt = String(r.Format_Post || '').toLowerCase();
  // Hors carrousel, un seul visuel : aucun autre format n'en publie plusieurs.
  if (fmt !== 'carrousel' && cartes.length > 1) cartes = [cartes[0]];
  // Repli sur le Titre : un post rédigé avant ce changement n'a pas de `Slides_JSON`. Il doit
  // quand même sortir une carte — bloquer la file serait pire que rendre le titre seul.
  if (!cartes.length) cartes = [{ titre: String(r.Titre || 'Max-Morrys').trim() || 'Max-Morrys' }];
  for (let i = 0; i < cartes.length; i++) {
    out.push({ json: { id: r.id, carte: cartes[i], image_index: i + 1, total_images: cartes.length } });
  }
}
return out;

// ── kit DS (29/10/2026) — bascule globale. false tant que le lot S45-S46 (sans Gabarit) n'est pas fini ;
// true = TOUT post sans Gabarit passe aussi au kit DS (gabarit choisi automatiquement).
const DS_PAR_DEFAUT = false;
function construireCharges(post, opts) {
  opts = opts || {};
  const GABARITS = ['affiche', 'citation', 'chiffre', 'avant_apres', 'question', 'etapes', 'coulisses', 'offre'];
  const s = (v) => (v == null ? '' : String(v)).trim();
  const liste = (v) => (Array.isArray(v) ? v.map(s).filter(Boolean) : []);
  const fp = s(post.Format_Post).toLowerCase();
  const fmtMap = { story: '9:16', reel: '9:16', short: '9:16', live: '9:16', carrousel: '4:5', post: '4:5', community_post: '1:1', thread: '1:1' };
  const format = fmtMap[fp] || '4:5';

  let cartes = [];
  let raw = opts.slides != null ? opts.slides : post.Slides_JSON;
  if (typeof raw === 'string') { try { raw = raw.trim() ? JSON.parse(raw) : []; } catch (e) { raw = []; } }
  if (Array.isArray(raw)) {
    for (const x of raw) {
      const o = x && typeof x === 'object' ? x : { titre: s(x) };
      if (!s(o.titre)) continue;
      cartes.push(o);
      if (cartes.length >= 10) break;
    }
  }
  if (fp !== 'carrousel' && cartes.length > 1) cartes = [cartes[0]];
  if (!cartes.length) cartes = [{ titre: s(post.Titre) || 'Max-Morrys' }];

  // Territoire : l'offre d'abord (c'est elle qui renvoie au site), puis la série et la cible.
  const offre = s(post.Offre), serie = s(post.Serie), cible = s(post.Cible);
  let territoire = 'informe';
  if (offre === 'Formations' || offre === 'Accompagnement') territoire = 'forme';
  else if (offre === 'Club Digitos' || offre === 'Rysmo') territoire = 'transforme';
  else if (offre === 'Agence') territoire = cible === 'Commerçants' ? 'digitalise' : 'agence';
  else if (cible === 'Commerçants') territoire = 'digitalise';
  else if (serie === 'CERCLE' || serie === 'COULISSES') territoire = 'transforme';
  else if (serie === 'PREUVE') territoire = 'forme';

  // Gabarit : celui du post (champ NocoDB `Gabarit`), sinon un choix par défaut prudent.
  const choisir = (c) => {
    const g = s(c.gabarit) || s(opts.gabarit) || s(post.Gabarit);
    if (GABARITS.indexOf(g) >= 0) return g;
    const m = s(c.corps).split(/\s+·\s+/).map(s).filter(Boolean);
    if (liste(c.options).length >= 2) return 'question';
    if (m.length >= 2 && m.every((x, k) => x.indexOf('ABCD'[k] + ' ') === 0 || x.indexOf('ABCD'[k] + '.') === 0)) return 'question';
    if (m.length >= 2 && m.length <= 5 && serie === 'ATELIER') return 'etapes';
    if (s(c.chiffre) && s(c.source)) return 'chiffre';
    if (liste(c.avant).length && liste(c.apres).length) return 'avant_apres';
    if (s(c.prix) || serie === 'OFFRE') return 'offre';
    if (liste(c.etapes).length >= 2) return 'etapes';
    if (serie === 'COULISSES') return 'coulisses';
    if (s(c.auteur)) return 'citation';
    return 'affiche';
  };
  const sourcil = [serie, s(post.Outil)].filter(Boolean).join(' · ');
  const avertissements = [];
  // `studio` : post phare fait à la main dans le studio NAYO. Le circuit rend quand même une
  // carte au kit DS (choix automatique) pour ne pas bloquer la file ; Max la remplace par
  // l'export du studio avant de valider.
  if (s(post.Gabarit) === 'studio') avertissements.push('studio : visuel provisoire, à remplacer par l’export NAYO avant validation');

  const charges = cartes.map((c, i) => {
    const total = cartes.length;
    const p = {
      kit: 'ds', format: format, template: 'poster',
      title: s(c.titre).slice(0, 140),
      eyebrow: s(c.sourcil) || sourcil,
      territoire: s(c.territoire) || territoire,
    };
    if (s(c.corps)) p.body = s(c.corps).slice(0, 260);
    if (s(c.cta)) p.cta = s(c.cta).slice(0, 44);
    if (s(c.fond) === 'nuit' || s(c.fond) === 'papier') p.fond = s(c.fond);

    if (fp === 'carrousel') {
      p.template = 'slide';
      p.gabarit = 'slide';
      p.slideRole = i === 0 ? 'cover' : i >= total - 1 ? 'outro' : 'body';
      p.slideIndex = i + 1;
      p.slideTotal = total;
      return p;
    }
    let g = choisir(c);
    // Corps « a · b · c » : la forme courte des rédacteurs pour une liste.
    const morceaux = s(c.corps).split(/\s+·\s+/).map(s).filter(Boolean);
    if (g === 'question') {
      let o = liste(c.options);
      if (o.length < 2 && morceaux.length >= 2) o = morceaux.map((m) => m.replace(/^[A-D][.)]?\s+/, ''));
      if (o.length >= 2) { p.options = o.slice(0, 4); delete p.body; } else g = 'affiche';
    }
    if (g === 'etapes') {
      let e = liste(c.etapes);
      if (e.length < 2 && morceaux.length >= 2) { e = morceaux; delete p.body; } // le corps EST la liste
      if (e.length >= 2) p.etapes = e.slice(0, 5); else g = 'affiche';
    }
    if (g === 'chiffre') {
      if (s(c.chiffre) && s(c.source)) { p.chiffre = s(c.chiffre); p.source = s(c.source); }
      else { avertissements.push('chiffre sans source → affiche (règle du monospace)'); g = 'affiche'; }
    }
    if (g === 'avant_apres') {
      if (liste(c.avant).length && liste(c.apres).length) {
        p.avant = liste(c.avant); p.apres = liste(c.apres);
        if (s(c.avantTitre)) p.avantTitre = s(c.avantTitre);
        if (s(c.apresTitre)) p.apresTitre = s(c.apresTitre);
      } else g = 'affiche';
    }
    if (g === 'offre') {
      for (const k of ['prix', 'prixUnite', 'prixNote', 'paiement']) if (s(c[k])) p[k] = s(c[k]);
      if (liste(c.points).length) p.points = liste(c.points).slice(0, 3);
      if (!p.prix && !p.points) avertissements.push('offre sans prix ni points : la carte ne montre que le titre');
    }
    if (g === 'citation') { if (s(c.auteur)) p.auteur = s(c.auteur); if (s(c.role)) p.role = s(c.role); }
    if (g === 'coulisses' && /^https:\/\//.test(s(c.photo))) p.photo = s(c.photo);
    p.gabarit = g;
    return p;
  });
  return { format: format, territoire: territoire, gabarits: charges.map((c) => c.gabarit), avertissements: avertissements, charges: charges };
}

// Compose la charge du moteur de rendu, une par créa. Le TEXTE vient du rédacteur (`carte`),
// la MISE EN FORME (gabarit, format, accent, eyebrow) des champs du contenu.
let RENDER_CARD_URL = '', RENDER_KEY = '';
try {
  const rc = $('Aplatir — Lire Config Render').all().map(i => i.json);
  const g = (kk) => { const r = rc.find(x => (x.fields ? x.fields.Cle : x.Cle) === kk); return r ? (r.fields ? r.fields.Valeur : r.Valeur) : ''; };
  RENDER_CARD_URL = g('RENDER_CARD_URL'); RENDER_KEY = g('RENDER_KEY');
} catch (e) {}

// Les champs du post, indexés par id : chaque créa retrouve SON contenu. L'appariement par
// position, longtemps utilisé ici, croisait deux posts dès qu'un item se perdait en route.
const parId = {};
try {
  for (const r of $('Aplatir — Lire rédigés').all()) {
    const f = r.json.fields || r.json;
    parId[r.json.id || f.id] = f;
  }
} catch (e) {}

const fmtMap = { story:'9:16', reel:'9:16', short:'9:16', carrousel:'4:5', post:'4:5', community_post:'1:1', thread:'1:1', live:'9:16' };
// Accent = couleur du Pilier, choisie pour rester lisible sur le bleu profond du fond.
const accMap = { 'Éducation':'turquoise', 'Inspiration':'violet', 'Produit':'orange', 'Autorité':'corail', 'Communauté':'vert', 'Autre':'orange' };

return $input.all().map(item => {
  const b = item.json || {};
  const f = parId[b.id] || {};
  const carte = b.carte || {};
  const fp = String(f.Format_Post || '').toLowerCase();
  const format = fmtMap[fp] || '4:5';

  // Le FORMAT décide du gabarit. Les gabarits plus riches (stat, checklist, versus, testimonial)
  // réclament des données que cette chaîne n'a pas — un chiffre, deux colonnes : c'est le Designer
  // qui les appelle sur ticket. Ici on ne produit que ce qu'on peut garantir.
  let template = 'poster';
  if (fp === 'story') template = 'ask';
  else if (fp === 'carrousel') template = 'slide';

  const idx = b.image_index || 1;
  const total = b.total_images || 1;
  const title = String(carte.titre || f.Titre || 'Max-Morrys').slice(0, 120);
  // Le mot surligné est le dernier mot long du titre : celui sur lequel l'œil s'arrête.
  const mots = title.replace(/[^\wÀ-ÿ\s]/g, ' ').split(/\s+/).filter(x => x.length > 3);

  const payload = {
    template: template,
    format: format,
    title: title,
    eyebrow: f.Serie || f.Pilier || '', // la série rend le rendez-vous reconnaissable
    highlight: mots.length ? mots[mots.length - 1] : '',
    accent: accMap[f.Pilier] || 'orange',
    curve: false
  };
  if (carte.corps) payload.body = String(carte.corps).slice(0, 240);
  if (carte.cta) payload.cta = String(carte.cta).slice(0, 40);
  if (template === 'ask' && Array.isArray(carte.options)) payload.options = carte.options;
  if (template === 'slide') {
    // La cover promet, l'outro récapitule, le reste porte une idée.
    payload.slideRole = idx === 1 ? 'cover' : (idx >= total ? 'outro' : 'body');
    payload.slideIndex = idx;
    payload.slideTotal = total;
  }

  // ── kit DS (29/10/2026) : un post qui porte un `Gabarit` est rendu au kit DS produit.
  // Sans Gabarit → charge historique ci-dessus, inchangée. Source : scripts/growth/nayo.mjs.
  if (DS_PAR_DEFAUT || String(f.Gabarit || '').trim()) {
    try {
      const ds = construireCharges(f).charges[idx - 1];
      if (ds) {
        for (const k of Object.keys(payload)) delete payload[k];
        Object.assign(payload, ds);
      }
    } catch (e) { /* en cas de doute, la charge historique part : la file ne bloque jamais */ }
  }
  return { json: { id: b.id, image_index: idx, total_images: total, carte: carte,
                   render_url: RENDER_CARD_URL, render_key: RENDER_KEY, payload: payload } };
});

// Regroupe les créas par contenu et décide du statut.
// Un post à qui il manque une image ne part PAS en validation : il attend en `image_needed`,
// visible dans la base, plutôt que d'arriver sur Telegram sans visuel — ou en carrousel amputé —
// puis d'échouer à la publication (Instagram refuse un post sans média).
const items = $input.all().map(i => i.json);
let mode = 'manual';
try {
  const cfg = $('Aplatir — Lire VALIDATION_MODE').all().map(i => i.json);
  if (cfg.length && cfg[0].Valeur) mode = String(cfg[0].Valeur).trim().toLowerCase();
} catch (e) {}
const statutComplet = mode === 'auto' ? 'validé' : 'prêt_à_valider';

const parId = {};
for (const it of items) {
  if (!parId[it.id]) parId[it.id] = { id: it.id, urls: [], cartes: [], erreurs: [], total: it.total_images || 1 };
  const g = parId[it.id];
  const rang = (it.image_index || 1) - 1;
  g.urls[rang] = it.public_url || '';
  g.cartes[rang] = it.carte || null;
  if (!it.public_url) g.erreurs.push('#' + (it.image_index || 1) + ' ' + (it.erreur || 'rendu indisponible'));
}

return Object.values(parId).map(g => {
  const urls = g.urls.filter(Boolean);
  const complet = urls.length === g.total;
  return { json: {
    id: g.id,
    Status: complet ? statutComplet : 'image_needed',
    Visuels_URLs: JSON.stringify(urls),
    Visual_Strategy: JSON.stringify({ cartes: g.cartes.filter(Boolean),
                                      rendus: urls.length + '/' + g.total,
                                      erreurs: g.erreurs })
  }};
});

// Aplatit la sortie NocoDB v3 {id, fields:{}} au format plat du noeud
// Airtable historique : {...champs, id} -> aucune expression aval a changer.
return $input.all().map(i => ({ json: { ...(i.json.fields || {}), id: i.json.id } }));

// Aplatit la sortie NocoDB v3 {id, fields:{}} au format plat du noeud
// Airtable historique : {...champs, id} -> aucune expression aval a changer.
return $input.all().map(i => ({ json: { ...(i.json.fields || {}), id: i.json.id } }));

// Réapparie la réponse du moteur avec sa demande (le nœud HTTP conserve l'ordre et le nombre
// d'items, y compris quand il échoue). Un rendu raté ressort sans URL plutôt qu'en exception :
// il doit coûter une carte, pas le workflow entier.
const b = $('Build — URL publique').all()[$itemIndex].json;
const resp = $input.item.json || {};
const url = (typeof resp.url === 'string' && resp.url) ? resp.url : '';
const err = url ? '' : String((resp.error && (resp.error.message || resp.error)) || resp.message || 'rendu indisponible').slice(0, 200);
return { json: { id: b.id, image_index: b.image_index, total_images: b.total_images,
                 carte: b.carte, public_url: url, erreur: err } };
